solutions.python:
class Solution:
    def countBits(self, n: int) -> List[int]:
        f = [0] * (n + 1)
        for i in range(1, n + 1):
            f[i] = f[i & (i - 1)] + 1
        return f

solutions.javascript:
function countBits(n) {
    const f = Array(n + 1).fill(0);
    for (let i = 1; i <= n; ++i) {
        f[i] = f[i & (i - 1)] + 1;
    }
    return f;
}

solutions.java:
class Solution {
    public int[] countBits(int n) {
        int[] f = new int[n + 1];
        for (int i = 1; i <= n; ++i) {
            f[i] = f[i & (i - 1)] + 1;
        }
        return f;
    }
}

